// Asana on a personal access token: every operation of Asana's REST API. actions.json is generated by
// `bun scripts/openapi-actions.ts asana`; tasks in a project start automations by webhook (triggers.ts).
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "Asana",
  base: "https://app.asana.com/api/1.0",
  tokenHelp: "app.asana.com/0/my-apps",
};

const ME = { method: "GET", path: "/users/me", query: [], headers: [] };

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
// the generator lifted the fields out of Asana's {"data": ...} body so an agent can see them; they go back in here
for (const { name, data } of (await Bun.file(file).json()).actions as { name: string; data?: [string, string][] }[]) {
  if (!data) continue;
  const action = actions[name]!;
  const run = action.run;
  action.run = (input: Record<string, unknown>, key) => {
    const rest = { ...input };
    const body: Record<string, unknown> = {};
    for (const [field, k] of data) {
      if (!(field in rest)) continue;
      body[k] = rest[field];
      delete rest[field];
    }
    return run({ ...rest, data: body }, key);
  };
}

export const asana: OwnApp = {
  app: "asana",
  name: "Asana",
  logo: "/logos/asana.svg",
  keyField: {
    label: "Personal access token",
    help: "app.asana.com/0/my-apps → Create new token, name it Emplio, and copy it. Emplio can then do whatever your Asana account can.",
    placeholder: "2/1200000000000000/...",
  },
  async check(key) {
    const { data } = (await call(api, key, ME, {})) as { data: { gid: string; name?: string; email?: string } };
    return data.name || data.email || data.gid;
  },
  push: {
    events,
    triggers,
    start: (key, connection, _event, config) => watch(api, key, connection, config),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: {
    ...actions,
    // Composio's names for the same calls, so saved automations carry over
    create_attachment_for_task: actions.create_attachment_for_object!,
    create_project_status_update: actions.create_status_for_object!,
    get_current_user: {
      description: "Who the connected Asana account is, and the workspaces it belongs to. Most calls need a workspace's gid from here.",
      readOnly: true,
      input: z.object({}),
      run: (_input: object, key: string) => call(api, key, ME, {}),
    },
  },
};
